"use strict";App.Http.EmailSettings=function(){return{save:function(emailSettings){var url=App.Utils.Url.siteUrl("email_settings/save");return $.post(url,{csrf_token:vars("csrf_token"),email_settings:emailSettings})},test:function(recipient){var url=App.Utils.Url.siteUrl("email_settings/test");return $.post(url,{csrf_token:vars("csrf_token"),recipient:recipient})},resend:function(appointmentId,recipientType,recipientEmail){var url=App.Utils.Url.siteUrl("email_settings/resend");return $.post(url,{csrf_token:vars("csrf_token"),appointment_id:appointmentId,recipient_type:recipientType,recipient_email:recipientEmail})},log:function(){var url=App.Utils.Url.siteUrl("email_settings/log");return $.ajax({url:url,method:"GET",cache:!1,data:{csrf_token:vars("csrf_token")}})}}}();